import json, pathlib, re
m = re.search(r'^stage: (\w+)$', context, re.M)
stage = m.group(1) if m else None

def part(name):
    at = context.find(name + ' ===\n')
    if at < 0:
        return ''
    start = at + len(name) + 5
    end = context.find('\n\n=== ', start)
    return context[start:] if end < 0 else context[start:end]

SKILL = '---\nname: fixture-recipe\ndescription: count the lines of a log\n---\nImport scripts/fixture_tool.py and call fixture_tool.count_lines(context).\n'
TOOL = 'def count_lines(text):\n    return len(text.splitlines())\n'
AGENT = '---\nname: fixture-reader\ndescription: reads a log\n---\nAnswer with one number.\n'
NUDGES = '[[nudge]]\nwhen = "error"\npattern = "Traceback"\nhint = "Read the error before you retry."\n'

if stage == 'inv':
    guidance = part('harness/guidance.md').rstrip('\n') + '\nWhen a question asks how many lines a log has, call skill("fixture-recipe").\n'
    files = {'skills/fixture-recipe/SKILL.md': SKILL, 'scripts/fixture_tool.py': TOOL}
    submit(json.dumps({'decision': 'EDIT', 'notes': ['the reference run counted lines by hand'], 'guidance': guidance, 'toml': {'read.max_turns': 60}, 'files': files}))
elif stage == 'dom':
    submit(json.dumps({'decision': 'KEEP_BASE', 'notes': ['no practitioner gap'], 'guidance': None, 'toml': {}, 'files': {}}))
elif stage == 'compose':
    submit(json.dumps({'decision': 'ADOPT', 'adopt': 'inv', 'notes': ['kept -> the counting skill -> the inv probe run used it'], 'guidance': None, 'toml': {}, 'files': {}}))
elif stage == 'reflect':
    submit(json.dumps({'domain': 'read', 'entry': {'cue': 'a question that counts lines of a long input', 'lesson': 'ship the count as a script named in a skill', 'evidence': 'row 1', 'confidence': 'low'}, 'edits': [{'component': 'skills/fixture-recipe', 'candidates': 'inv', 'change': 'a counting skill', 'observed': 'the inv run imported it', 'verdict': 'confounded'}]}))
elif pathlib.Path('.git').is_dir():
    p = pathlib.Path('calc/__init__.py')
    if p.exists():
        p.write_text(p.read_text().replace('a - b', 'a + b'))
    submit('done')
else:
    submit(len(context.splitlines()))

